// All Star: quick entry of the monthly sales report. The store sees the Stravik parts invoiced to it (how many are still
// to report), types how many it sold and which Hero sold them, and sends: no file needed. The POS export upload stays,
// with drag-and-drop. Database: stravik_sales_quick(period); sending uses stravik_sales_submit().
const fs = require("fs");
function edit(file, pairs) {
  let s = fs.readFileSync(file, "utf8");
  for (const [from, to] of pairs) {
    const n = s.split(from).length - 1;
    if (n !== 1) { console.error(`${file}: expected the text once, found it ${n} times: ${from.slice(0, 70)}`); process.exit(1); }
    s = s.replace(from, () => to);
  }
  fs.writeFileSync(file, s);
  console.log(file + ": updated");
}
