{ const f = "assets/allstar.css", s = fs.readFileSync(f, "utf8"); if (s.includes(".qk-ways{")) { console.error(f + ": already there"); process.exit(1); } fs.writeFileSync(f, s + "\n/* sending the monthly report: two ways in, and the quick entry list */\n.qk-ways{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:12px 0 8px}\n.qk-way{position:relative;display:grid;gap:4px;text-align:left;font:inherit;padding:18px 20px;border-radius:12px;border:1.5px solid var(--line);background:var(--card);color:var(--ink);cursor:pointer;transition:border-color .15s,transform .15s}\n.qk-way b{font-size:18px}\n.qk-way span{color:var(--muted);font-size:14.5px}\n.qk-way em{position:absolute;top:12px;right:14px;font-style:normal;font-weight:700;font-size:12px;padding:3px 9px;border-radius:999px;background:var(--as-gold);color:#2b1f00}\n.qk-way:hover,.qk-way.drag{border-color:var(--as-gold);transform:translateY(-1px)}\n.qk-way.main{border-color:var(--as-gold);background:linear-gradient(180deg,rgba(201,154,28,.10),transparent 70%),var(--card)}\n.qk-find{display:grid;gap:5px;max-width:420px;margin:6px 0 12px;font-size:13.5px;font-weight:600;color:var(--muted)}\n.qk-find input{font:inherit;font-size:15px;padding:9px 11px;border:1.5px solid var(--line);border-radius:8px;background:var(--card);color:var(--ink)}\n.qk-list{display:grid;gap:8px;margin:8px 0 10px}\n.qk-row{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,1fr);gap:8px 18px;align-items:start;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--card)}\n.qk-row.has{border-color:var(--as-gold);box-shadow:inset 4px 0 0 var(--as-gold)}\n.qk-part{display:grid;gap:2px;min-width:0}\n.qk-part b{font-size:16px}\n.qk-part span{color:var(--ink);font-size:14px}\n.qk-part small{color:var(--muted);font-size:13px}\n.qk-splits{display:grid;gap:6px}\n.qk-split{display:flex;flex-wrap:wrap;align-items:center;gap:8px}\n.qk-step{display:inline-flex;align-items:stretch;border:1.5px solid var(--line);border-radius:8px;overflow:hidden;background:var(--card)}\n.qk-step button{width:38px;font:700 18px/1 inherit;background:var(--paper);border:0;color:var(--ink);cursor:pointer}\n.qk-step button:hover{background:rgba(201,154,28,.18)}\n.qk-step input{width:62px;text-align:center;font:inherit;font-size:16px;font-weight:700;border:0;border-left:1px solid var(--line);border-right:1px solid var(--line);padding:8px 4px;background:var(--card);color:var(--ink);-moz-appearance:textfield}\n.qk-step input::-webkit-outer-spin-button,.qk-step input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n.qk-hero{flex:1 1 160px;max-width:260px}\n.qk-warn{margin:0;font-size:13px;color:#a4441b}\n.qk-warn:empty{display:none}\n.qk-addbox{display:grid;gap:4px;max-width:520px;margin:6px 0 12px}\n.qk-addbox label{display:grid;gap:5px;font-size:13.5px;font-weight:600;color:var(--muted)}\n@media (max-width:760px){.qk-ways,.qk-row{grid-template-columns:1fr}}\n"); console.log(f + ": updated"); }
